11	#ifndef TROWSUM_HPP
12	#define TROWSUM_HPP
13	
14	#include "TRowReduceOps.hpp"
15	
16	namespace pto {
17	
18	// Float/Half operation traits (for vcadd-based implementation)
19	template <typename T>
20	struct TRowSumOp : TRowReduceOp<T, TRowSumOp<T>> {
21	    using ReduceOp = TRowReduceOp<T, TRowSumOp<T>>;
22	    PTO_INTERNAL static void BinInstrImpl(
23	        __ubuf__ T* dst, __ubuf__ T* src0, __ubuf__ T* src1, uint8_t rptTimes, uint16_t dstRptStride,
24	        uint16_t src0RptStride, uint16_t src1RptStride, uint8_t dstBlockStride = 1, uint8_t src0BlockStride = 1,
25	        uint8_t src1BlockStride = 1)
26	    {
27	        vadd(
28	            dst, src0, src1, rptTimes, dstBlockStride, src0BlockStride, src1BlockStride, dstRptStride, src0RptStride,
29	            src1RptStride);
30	    }
31	
32	    PTO_INTERNAL static void ReduceInstrImpl(
33	        __ubuf__ T* dst, __ubuf__ T* src, uint8_t rptTimes, uint16_t dstRptStride, uint16_t srcBlkStride,
34	        uint16_t srcRptStride)
35	    {
36	        vcadd(dst, src, rptTimes, dstRptStride, srcBlkStride, srcRptStride, false);
37	    }
38	
39	    PTO_INTERNAL static void GroupReduceInstrImpl(
40	        __ubuf__ T* dst, __ubuf__ T* src, uint8_t rptTimes, uint16_t dstRptStride, uint16_t src0Stride,
41	        uint16_t src1Stride)
42	    {
43	        vcgadd(dst, src, rptTimes, dstRptStride, src0Stride, src1Stride);
44	    }
45	
46	    template <int TmpCols, int SrcCols, uint32_t TmpStride, uint32_t SrcStride, uint8_t ElemPerRpt>
47	    PTO_INTERNAL static void FillTmp(__ubuf__ T* tmp, __ubuf__ T* src, int srcRptPerRow, int validRow, int validCol)
48	    {
49	        for (int i = 0; i < srcRptPerRow / 2; ++i) {
50	            ReduceOp::template BinInstrByMode<
51	                true, TmpCols, SrcCols, SrcCols, TmpStride, SrcStride, SrcStride, ElemPerRpt>(
52	                tmp + i * ElemPerRpt, src + (i * 2) * ElemPerRpt, src + (i * 2 + 1) * ElemPerRpt, validRow);
53	            pipe_barrier(PIPE_V);
54	        }
55	        if (srcRptPerRow != 1 && srcRptPerRow % 2 == 1) {
56	            ReduceOp::template BinInstrByMode<
57	                true, TmpCols, TmpCols, SrcCols, TmpStride, TmpStride, SrcStride, ElemPerRpt>(
58	                tmp, tmp, src + (srcRptPerRow - 1) * ElemPerRpt, validRow);
59	            pipe_barrier(PIPE_V);
60	        }
61	    }
62	
63	    template <int TmpCols, int SrcCols, uint32_t TmpStride, uint32_t SrcStride, uint8_t ElemPerRpt>
64	    PTO_INTERNAL static void TmpProc(__ubuf__ T* tmp, __ubuf__ T* src, int srcRptPerRow, int validRow)
65	    {
66	        unsigned curLen = srcRptPerRow / 2;
67	        unsigned loopRemain;
68	        int i;
69	        while (curLen > 1) {
70	            for (i = 0; i < curLen / 2; ++i) {
71	                ReduceOp::template BinInstrByMode<
72	                    true, TmpCols, TmpCols, TmpCols, TmpStride, TmpStride, TmpStride, ElemPerRpt>(
73	                    tmp + i * ElemPerRpt, tmp + i * 2 * ElemPerRpt, tmp + (i * 2 + 1) * ElemPerRpt, validRow);
74	                pipe_barrier(PIPE_V);
75	            }
76	            loopRemain = curLen % 2;
77	            curLen /= 2;
78	            if (loopRemain > 0) {
79	                ReduceOp::template BinInstrByMode<
80	                    true, TmpCols, TmpCols, TmpCols, TmpStride, TmpStride, TmpStride, ElemPerRpt>(
81	                    tmp + (curLen - 1) * ElemPerRpt, tmp + (curLen - 1) * ElemPerRpt, tmp + curLen * 2 * ElemPerRpt,
82	                    validRow);
83	                pipe_barrier(PIPE_V);
84	            }
85	        }
86	    }
87	};
88	
89	template <uint16_t elemsPerVL, typename T>
90	PTO_INTERNAL void SumLastBlockElements(__ubuf__ T* dst, __ubuf__ T* tmp)
91	{
92	    set_flag(PIPE_V, PIPE_S, EVENT_ID0);
93	    wait_flag(PIPE_V, PIPE_S, EVENT_ID0);
94	
95	    T sum = 0;
96	    for (uint16_t i = 0; i < elemsPerVL; ++i) {
97	        sum += tmp[i];
98	    }
99	    dst[0] = sum;
100	
101	    set_flag(PIPE_S, PIPE_V, EVENT_ID0);
102	    wait_flag(PIPE_S, PIPE_V, EVENT_ID0);
103	}
104	
105	template <typename T, typename TileDataOut, typename TileDataIn, typename TileDataTmp>
106	__tf__ PTO_INTERNAL void TRowSum(
107	    typename TileDataOut::TileDType __out__ dstData, typename TileDataIn::TileDType __in__ srcData,
108	    typename TileDataTmp::TileDType __in__ tmpData, int validCol, int validRow)
109	{
