111	    __ubuf__ T* src = (__ubuf__ T*)__cce_get_tile_ptr(srcData);
112	    __ubuf__ T* tmp = (__ubuf__ T*)__cce_get_tile_ptr(tmpData);
113	
114	    if constexpr (std::is_same_v<T, int16_t> || std::is_same_v<T, int32_t>) {
115	        // Integer implementation (follows TROWPROD pattern)
116	        constexpr unsigned dstRowStride = TileDataOut::RowStride;
117	        constexpr unsigned srcRowStride = TileDataIn::RowStride;
118	        constexpr unsigned tmpRowStride = TileDataTmp::RowStride;
119	        constexpr unsigned elemsPerBlock = BLOCK_BYTE_SIZE / sizeof(T);
120	        unsigned blocksPerRow = validCol / elemsPerBlock;
121	        unsigned elemsLessThanBlock = validCol % elemsPerBlock;
122	
123	        set_mask_count();
124	        for (unsigned row = 0; row < validRow; ++row, dst += dstRowStride, src += srcRowStride) {
125	            set_vector_mask(0, elemsPerBlock);
126	
127	            // Initialize tmp with 0
128	            vector_dup(tmp, (T)PadValueMap<T, PadValue::Zero>::value, 1, 1, 1, 0, 0);
129	            pipe_barrier(PIPE_V);
130	
131	            // Accumulate using vadd
132	            for (unsigned block = 0; block < blocksPerRow; ++block) {
133	                vadd(tmp, tmp, src + block * elemsPerBlock, 1, 0, 0, 1, 0, 0, 1);
134	                pipe_barrier(PIPE_V);
135	            }
136	
137	            // Handle remaining elements
138	            if (elemsLessThanBlock > 0) {
139	                set_vector_mask(0, elemsLessThanBlock);
140	                vadd(tmp, tmp, src + blocksPerRow * elemsPerBlock, 1, 0, 0, 1, 0, 0, 1);
141	                pipe_barrier(PIPE_V);
142	            }
143	
144	            SumLastBlockElements<elemsPerBlock>(dst, tmp);
145	        }
146	
147	        set_mask_norm();
148	        set_vector_mask(-1, -1);
149	    } else {
150	        // Float/Half implementation (original vcadd-based)
151	        TRowReduceInstr<TRowSumOp<T>, T, TileDataOut, TileDataIn, TileDataTmp>(dst, src, tmp, validCol, validRow);
152	    }
153	}
