18	template <typename T, int dstCols, int srcCols, unsigned dstStride, unsigned srcStride>
19	PTO_INTERNAL void TPartCopyInstr(
20	    __ubuf__ T* dstPtr, __ubuf__ T* srcPtr, uint64_t validRow, uint64_t validCol, uint64_t startRow)
21	{
22	    validRow -= startRow;
23	    srcPtr += startRow * srcStride;
24	    dstPtr += startRow * dstStride;
25	
26	    if constexpr (dstCols == srcCols) {
