30	        pto_copy_ubuf_to_ubuf(dstPtr, srcPtr, 1, blockLen, 1, 1);
31	    } else {
32	        set_mask_count(); // counter mode
33	        SetVectorCount(validCol);
34	        uint64_t blockLen = (validCol * sizeof(T) + BLOCK_BYTE_SIZE - 1) / BLOCK_BYTE_SIZE;
35	        for (uint64_t i = 0; i < validRow; i++) {
36	            pto_copy_ubuf_to_ubuf(dstPtr + i * dstStride, srcPtr + i * srcStride, 1, blockLen, 1, 1);
37	        }
38	    }
39	    set_mask_norm();
