41	}
42	
43	template <typename Op, typename T, unsigned dstStride, unsigned src0Stride, unsigned src1Stride>
44	PTO_INTERNAL void PartCountMode(
45	    __ubuf__ T* dstPtr, __ubuf__ T* src0Ptr, __ubuf__ T* src1Ptr, unsigned validRow, unsigned validCol)
46	{
47	    set_mask_count();
48	    SetVectorCount(validCol);
49	    for (unsigned i = 0; i < validRow; i++) {
50	        Op::PartInstr(dstPtr + i * dstStride, src0Ptr + i * src0Stride, src1Ptr + i * src1Stride, 0);
51	    }
52	    set_mask_norm();
53	    SetFullVecMaskByDType<T>();
54	}
55	
56	template <
57	    typename Op, typename T, int dstRow, unsigned elementsPerRepeat, unsigned blockSizeElem, unsigned dstStride,
58	    unsigned src0Stride, unsigned src1Stride>
59	PTO_INTERNAL void PartNormModeTail(
60	    __ubuf__ T* dstPtr, __ubuf__ T* src0Ptr, __ubuf__ T* src1Ptr, unsigned validRow, unsigned validCol)
61	{
62	    unsigned numRepeatPerCol = validRow / REPEAT_MAX;
63	    unsigned numRemainPerCol = validRow % REPEAT_MAX;
64	    unsigned dstRepeatStride = dstStride / blockSizeElem;
65	    unsigned src0RepeatStride = src0Stride / blockSizeElem;
66	    unsigned src1RepeatStride = src1Stride / blockSizeElem;
67	    unsigned dstRepeatMaxStride = REPEAT_MAX * dstStride;
68	    unsigned src0RepeatMaxStride = REPEAT_MAX * src0Stride;
69	    unsigned src1RepeatMaxStride = REPEAT_MAX * src1Stride;
70	    unsigned numRemainPerLine = validCol % elementsPerRepeat;
71	    SetContMaskByDType<T>(numRemainPerLine);
72	    if constexpr (dstRow >= REPEAT_MAX) {
73	        for (unsigned j = 0; j < numRepeatPerCol; j++) {
74	            Op::PartInstr(
75	                dstPtr + j * dstRepeatMaxStride, src0Ptr + j * src0RepeatMaxStride, src1Ptr + j * src1RepeatMaxStride,
76	                REPEAT_MAX, dstRepeatStride, src0RepeatStride, src1RepeatStride);
77	        }
78	    }
79	    if (numRemainPerCol) {
80	        Op::PartInstr(
81	            dstPtr + numRepeatPerCol * dstRepeatMaxStride, src0Ptr + numRepeatPerCol * src0RepeatMaxStride,
82	            src1Ptr + numRepeatPerCol * src1RepeatMaxStride, numRemainPerCol, dstRepeatStride, src0RepeatStride,
83	            src1RepeatStride);
84	    }
85	    SetFullVecMaskByDType<T>();
86	}
87	
88	template <
89	    typename Op, typename T, int dstRow, int dstCol, unsigned elementsPerRepeat, unsigned blockSizeElem,
90	    unsigned dstStride, unsigned src0Stride, unsigned src1Stride>
91	PTO_INTERNAL void PartNormMode(
92	    __ubuf__ T* dstPtr, __ubuf__ T* src0Ptr, __ubuf__ T* src1Ptr, unsigned validRow, unsigned validCol)
93	{
94	    unsigned numRepeatPerLine = validCol / elementsPerRepeat;
95	    unsigned numRemainPerLine = validCol % elementsPerRepeat;
96	    if constexpr (dstCol >= static_cast<int>(elementsPerRepeat)) {
97	        unsigned numRepeatPerCol = validRow / REPEAT_MAX;
98	        unsigned numRemainPerCol = validRow % REPEAT_MAX;
99	        unsigned dstRepeatStride = dstStride / blockSizeElem;
100	        unsigned src0RepeatStride = src0Stride / blockSizeElem;
101	        unsigned src1RepeatStride = src1Stride / blockSizeElem;
102	        unsigned dstRepeatMaxStride = REPEAT_MAX * dstStride;
103	        unsigned src0RepeatMaxStride = REPEAT_MAX * src0Stride;
104	        unsigned src1RepeatMaxStride = REPEAT_MAX * src1Stride;
105	        for (unsigned i = 0; i < numRepeatPerLine; i++) {
106	            if constexpr (dstRow >= REPEAT_MAX) {
107	                for (unsigned j = 0; j < numRepeatPerCol; j++) {
108	                    Op::PartInstr(
109	                        dstPtr + j * dstRepeatMaxStride + i * elementsPerRepeat,
110	                        src0Ptr + j * src0RepeatMaxStride + i * elementsPerRepeat,
111	                        src1Ptr + j * src1RepeatMaxStride + i * elementsPerRepeat, REPEAT_MAX, dstRepeatStride,
112	                        src0RepeatStride, src1RepeatStride);
113	                }
114	            }
115	            if (numRemainPerCol) {
116	                Op::PartInstr(
117	                    dstPtr + numRepeatPerCol * dstRepeatMaxStride + i * elementsPerRepeat,
118	                    src0Ptr + numRepeatPerCol * src0RepeatMaxStride + i * elementsPerRepeat,
119	                    src1Ptr + numRepeatPerCol * src1RepeatMaxStride + i * elementsPerRepeat, numRemainPerCol,
120	                    dstRepeatStride, src0RepeatStride, src1RepeatStride);
121	            }
122	        }
123	        unsigned offset = numRepeatPerLine * elementsPerRepeat;
124	        dstPtr += offset;
125	        src0Ptr += offset;
126	        src1Ptr += offset;
127	    }
128	    if (numRemainPerLine) {
129	        PartNormModeTail<Op, T, dstRow, elementsPerRepeat, blockSizeElem, dstStride, src0Stride, src1Stride>(
130	            dstPtr, src0Ptr, src1Ptr, validRow, validCol);
131	    }
132	}
133	
134	template <
135	    typename Op, typename T, int dstRow, int dstCol, unsigned elementsPerRepeat, unsigned blockSizeElem,
136	    unsigned dstStride, unsigned src0Stride, unsigned src1Stride>
137	PTO_INTERNAL void TPartOps(
138	    __ubuf__ T* dstPtr, __ubuf__ T* src0Ptr, __ubuf__ T* src1Ptr, unsigned validRow, unsigned validCol)
139	{
140	    bool constexpr strideOverFlag =
141	        ((src0Stride / blockSizeElem > REPEAT_STRIDE_MAX) || (src1Stride / blockSizeElem > REPEAT_STRIDE_MAX) ||
142	         (dstStride / blockSizeElem > REPEAT_STRIDE_MAX));
143	    if constexpr (strideOverFlag) {
144	        PartCountMode<Op, T, dstStride, src0Stride, src1Stride>(dstPtr, src0Ptr, src1Ptr, validRow, validCol);
145	    } else {
146	        if (validRow < CeilDivision(validCol, elementsPerRepeat) * CeilDivision(validRow, REPEAT_MAX)) {
147	            PartCountMode<Op, T, dstStride, src0Stride, src1Stride>(dstPtr, src0Ptr, src1Ptr, validRow, validCol);
148	        } else {
149	            PartNormMode<Op, T, dstRow, dstCol, elementsPerRepeat, blockSizeElem, dstStride, src0Stride, src1Stride>(
150	                dstPtr, src0Ptr, src1Ptr, validRow, validCol);
151	        }
152	    }
153	}
154	
155	template <
156	    typename Op, typename T, int dstCol, int src0Col, int dstRow, unsigned elementsPerRepeat, unsigned blockSizeElem,
157	    unsigned dstRowStride, unsigned src0RowStride, unsigned src1RowStride>
158	PTO_INTERNAL void TPartInstr(
159	    __ubuf__ T* dstPtr, __ubuf__ T* src0Ptr, __ubuf__ T* src1Ptr, unsigned src0ValidRow, unsigned src0ValidCol,
160	    unsigned src1ValidRow, unsigned src1ValidCol, unsigned dstValidRow, unsigned dstValidCol)
161	{
162	    bool condSrc1EqDst = (src1ValidRow == dstValidRow && src1ValidCol == dstValidCol);
163	    bool condSrc1RowLtDst = (src1ValidRow < dstValidRow && src1ValidCol == dstValidCol);
164	    bool condSrc1ColLtDst = (src1ValidRow <= dstValidRow && src1ValidCol < dstValidCol);
165	
166	    if (condSrc1RowLtDst) { // src1Row < dstRow
167	        if (src1ValidRow != 0) {
168	            TPartOps<
169	                Op, T, dstRow, dstCol, elementsPerRepeat, blockSizeElem, dstRowStride, src0RowStride, src1RowStride>(
170	                dstPtr, src0Ptr, src1Ptr, src1ValidRow, src1ValidCol);
171	        }
172	        TPartCopyInstr<T, dstCol, src0Col, dstRowStride, src0RowStride>(
173	            dstPtr, src0Ptr, src0ValidRow, dstValidCol, src1ValidRow);
174	    } else if (condSrc1ColLtDst) { // src1Col < dstCol
175	        TPartCopyInstr<T, dstCol, src0Col, dstRowStride, src0RowStride>(dstPtr, src0Ptr, src0ValidRow, dstValidCol, 0);
176	        if (src1ValidCol != 0) {
177	            pipe_barrier(PIPE_V);
178	            TPartOps<
179	                Op, T, dstRow, dstCol, elementsPerRepeat, blockSizeElem, dstRowStride, src1RowStride, dstRowStride>(
180	                dstPtr, src1Ptr, dstPtr, src1ValidRow, src1ValidCol);
181	        }
182	    } else if (condSrc1EqDst) { // src0 == src1 == dst
183	        TPartOps<Op, T, dstRow, dstCol, elementsPerRepeat, blockSizeElem, dstRowStride, src0RowStride, src1RowStride>(
184	            dstPtr, src0Ptr, src1Ptr, dstValidRow, dstValidCol);
185	    } else {
186	        // unsupported other conditions
187	        PTO_ASSERT(
188	            condSrc1EqDst || condSrc1RowLtDst || condSrc1ColLtDst,
189	            "TPARTOPS: At most one entry in the valid-rows and valid-cols of src0 and src1 is smaller than dst.");
190	    }
191	}
192	} // namespace pto
193	#endif
