11	#ifndef TROWSUM_HPP
12	#define TROWSUM_HPP
13	#include "pto/cpu/tile_offsets.hpp"
14	#include "pto/cpu/parallel.hpp"
15	
16	namespace pto {
17	template <typename TileDst, typename TileSrc>
18	void TRowSum(typename TileDst::TileDType dst, typename TileSrc::TileDType src, uint16_t M, uint16_t N)
19	{
20	    cpu::parallel_for_1d(0, M, static_cast<std::size_t>(M) * N, [&](std::size_t i) {
21	        TypeSum<TileDst> sum = 0;
22	        if constexpr (TileSrc::SFractal == SLayout::NoneBox && TileSrc::isRowMajor) {
23	            const std::size_t base = i * TileSrc::Cols;
24	            PTO_CPU_VECTORIZE_LOOP
25	            for (std::size_t j = 0; j < N; ++j) {
26	                sum += src[base + j];
27	            }
28	        } else {
29	            for (std::size_t j = 0; j < N; ++j) {
30	                sum += src[GetTileElementOffset<TileSrc>(i, j)];
31	            }
32	        }
33	        if constexpr (TileDst::SFractal == SLayout::NoneBox && TileDst::isRowMajor) {
34	            dst[i * TileDst::Cols] = static_cast<typename TileDst::DType>(sum);
35	        } else {
36	            dst[GetTileElementOffset<TileDst>(i, 0)] = static_cast<typename TileDst::DType>(sum);
37	        }
38	    });
39	}
40	
41	template <typename TileDst, typename TileSrc>
42	PTO_INTERNAL void CheckRSValid()
43	{
44	    using SrcType = typename TileSrc::DType;
45	    using DstType = typename TileDst::DType;
46	    static_assert(
47	        (std::is_same_v<SrcType, half> && std::is_same_v<DstType, half>) ||                 // f162f16
48	            (std::is_same_v<SrcType, bfloat16_t> && std::is_same_v<DstType, bfloat16_t>) || // bf162bf16
49	            (std::is_same_v<SrcType, half> && std::is_same_v<DstType, float>) ||            // f162f32
50	            (std::is_same_v<SrcType, bfloat16_t> && std::is_same_v<DstType, float>) ||      // bf162f32
51	            (std::is_same_v<SrcType, float> && std::is_same_v<DstType, float>) ||           // f322f32
52	            (std::is_same_v<SrcType, int16_t> && std::is_same_v<DstType, int16_t>) ||       // i162i16
53	            (std::is_same_v<SrcType, int16_t> && std::is_same_v<DstType, int32_t>) ||       // i162i32
54	            (std::is_same_v<SrcType, int32_t> && std::is_same_v<DstType, int32_t>)          // i322i32
55	        ,
56	        "Not supported data type");
57	    static_assert((TileSrc::Rows == TileDst::Rows), "Inconsistent number of m, n");
58	}
59	
60	template <typename TileDataOut, typename TileDataIn, typename TileDataTmp>
61	PTO_INTERNAL void TROWSUM_IMPL(TileDataOut& dstTile, TileDataIn& srcTile, TileDataTmp& tmp)
62	{
63	    CheckRSValid<TileDataOut, TileDataIn>();
64	
65	    uint16_t m = srcTile.GetValidRow();
66	    uint16_t n = srcTile.GetValidCol();
67	
68	    TRowSum<TileDataOut, TileDataIn>(dstTile.data(), srcTile.data(), m, n);
69	}
70	} // namespace pto
71	#endif
