10	
11	#ifndef T_ROW_REDUCE_OPS_HPP
12	#define T_ROW_REDUCE_OPS_HPP
13	#include <pto/common/utils.hpp>
14	#include <pto/common/type.hpp>
15	
16	#ifndef B16_REPEAT_MAX
17	#define B16_REPEAT_MAX 65535
18	#endif
19	
20	namespace pto {
21	template <typename T, typename InstrOp>
22	struct TRowReduceOp {
23	    PTO_INTERNAL static void BinInstr(
24	        __ubuf__ T* dst, __ubuf__ T* src0, __ubuf__ T* src1, uint8_t rptTimes, uint16_t dstRptStride,
25	        uint16_t src0RptStride, uint16_t src1RptStride)
26	    {
27	        InstrOp::BinInstrImpl(dst, src0, src1, rptTimes, dstRptStride, src0RptStride, src1RptStride);
28	    }
29	
30	    PTO_INTERNAL static void ReduceInstr(
31	        __ubuf__ T* dst, __ubuf__ T* src, uint8_t rptTimes, uint16_t dstRptStride, uint16_t srcBlkStride,
32	        uint16_t srcRptStride)
33	    {
34	        InstrOp::ReduceInstrImpl(dst, src, rptTimes, dstRptStride, srcBlkStride, srcRptStride);
35	    }
36	
37	    template <int Rows, int ValidRow, int Cols, int ValidCol>
38	    PTO_INTERNAL static void ReduceOptFP32_64x128(__ubuf__ T* dst, __ubuf__ T* src, __ubuf__ T* tmp)
39	    {
40	        static_assert(std::is_same_v<T, float>, "This optimization is only for float type.");
41	        static_assert(
42	            Rows == 64 && ValidRow == 64 && Cols == 128 && ValidCol == 128,
43	            "This optimization is only for [64, 128] input.");
44	        // [64, 128] -> [64, 16]
45	        InstrOp::GroupReduceInstrImpl(tmp, src, ValidRow * 2, 1, 1, 8);
46	        pipe_barrier(PIPE_V);
47	        // [64, 16] -> [64, 8]
48	        InstrOp::BinInstrImpl(tmp, tmp, tmp + 8, ValidRow / 8, 8, 16, 16, 1, 2, 2);
49	        pipe_barrier(PIPE_V);
50	        // [64, 8] -> [64, 1]
51	        InstrOp::GroupReduceInstrImpl(dst, tmp, ValidRow / 8, 1, 1, 8);
52	        pipe_barrier(PIPE_V);
53	        return;
54	    }
55	
56	    template <int Rows, int ValidRow, int Cols, int ValidCol>
57	    PTO_INTERNAL static void ReduceOptFP32_32x256(__ubuf__ T* dst, __ubuf__ T* src, __ubuf__ T* tmp)
58	    {
59	        static_assert(std::is_same_v<T, float>, "This optimization is only for float type.");
60	        static_assert(
61	            Rows == 32 && ValidRow == 32 && Cols == 256 && ValidCol == 256,
62	            "This optimization is only for [32, 256] input.");
63	        // [32, 256] -> [32, 32]
64	        InstrOp::GroupReduceInstrImpl(tmp, src, ValidRow * 4, 1, 1, 8);
65	        pipe_barrier(PIPE_V);
66	        // [32, 32] -> [32, 16]
67	        InstrOp::BinInstrImpl(tmp, tmp, tmp + 8, ValidRow / 4, 8, 16, 16, 1, 2, 2);
68	        pipe_barrier(PIPE_V);
69	        // [32, 16] -> [32, 8]
70	        InstrOp::BinInstrImpl(tmp, tmp, tmp + 8, ValidRow / 8, 8, 16, 16, 1, 2, 2);
71	        pipe_barrier(PIPE_V);
72	        // [32, 8] -> [32, 1]
73	        InstrOp::GroupReduceInstrImpl(dst, tmp, ValidRow / 8, 1, 1, 8);
74	        pipe_barrier(PIPE_V);
75	        return;
76	    }
77	
78	    template <int Rows, int ValidRow, int Cols, int ValidCol>
79	    PTO_INTERNAL static void ReduceOptFP32_16x512(__ubuf__ T* dst, __ubuf__ T* src, __ubuf__ T* tmp)
80	    {
81	        static_assert(std::is_same_v<T, float>, "This optimization is only for float type.");
82	        static_assert(
83	            Rows == 16 && ValidRow == 16 && Cols == 512 && ValidCol == 512,
84	            "This optimization is only for [16, 512] input.");
85	        // [16, 512] -> [16, 64]
86	        InstrOp::GroupReduceInstrImpl(tmp, src, ValidRow * 8, 1, 1, 8);
87	        pipe_barrier(PIPE_V);
88	        // [16, 64] -> [16, 8]
89	        InstrOp::GroupReduceInstrImpl(tmp, tmp, ValidRow, 1, 1, 8);
90	        pipe_barrier(PIPE_V);
91	        // [16, 8] -> [16, 1]
92	        InstrOp::GroupReduceInstrImpl(dst, tmp, ValidRow / 8, 1, 1, 8);
93	        pipe_barrier(PIPE_V);
94	        return;
95	    }
96	
97	    template <int Rows, int ValidRow, int Cols, int ValidCol>
98	    PTO_INTERNAL static void ReduceOptFP32_8x1024(__ubuf__ T* dst, __ubuf__ T* src, __ubuf__ T* tmp)
99	    {
100	        static_assert(std::is_same_v<T, float>, "This optimization is only for float type.");
101	        static_assert(
102	            Rows == 8 && ValidRow == 8 && Cols == 1024 && ValidCol == 1024,
103	            "This optimization is only for [8, 1024] input.");
104	        // [8, 1024] -> [8, 128]
105	        InstrOp::GroupReduceInstrImpl(tmp, src, ValidRow * 16, 1, 1, 8);
106	        pipe_barrier(PIPE_V);
107	        // [8, 128] -> [8, 16]
108	        InstrOp::GroupReduceInstrImpl(tmp, tmp, ValidRow * 2, 1, 1, 8);
109	        pipe_barrier(PIPE_V);
110	        // [8, 16] -> [8, 8]
111	        InstrOp::BinInstrImpl(tmp, tmp, tmp + 8, ValidRow / 8, 8, 16, 16, 1, 2, 2);
112	        pipe_barrier(PIPE_V);
113	        // [8, 8] -> [8, 1]
114	        InstrOp::GroupReduceInstrImpl(dst, tmp, ValidRow / 8, 1, 1, 8);
115	        pipe_barrier(PIPE_V);
116	        return;
117	    }
118	
119	    template <bool CntModeEn, int Cols, uint32_t DstStride, uint32_t SrcStride, uint8_t ElemPerRpt>
120	    PTO_INTERNAL static void ReduceInstrByMode(__ubuf__ T* dst, __ubuf__ T* src, unsigned rptTimes)
121	    {
122	        if constexpr (DstStride > B16_REPEAT_MAX) {
123	            for (int i = 0; i < rptTimes; i++) {
124	                ReduceInstr(dst + i * DstStride, src + i * Cols, 1, 0, 1, 0);
125	            }
126	        } else if constexpr (CntModeEn) {
127	            set_mask_count();
128	            set_vector_mask(0, (uint32_t)rptTimes * ElemPerRpt);
129	            ReduceInstr(dst, src, 0, DstStride, 1, SrcStride);
130	            set_mask_norm();
131	            set_vector_mask(-1, -1);
132	        } else {
133	            ReduceInstr(dst, src, rptTimes, DstStride, 1, SrcStride);
134	        }
135	    }
136	
137	    template <
138	        bool CntModeEn, int DstCols, int Src0Cols, int Src1Cols, uint32_t DstStride, uint32_t Src0RptStride,
139	        uint32_t Src1RptStride, uint8_t ElemPerRpt>
140	    PTO_INTERNAL static void BinInstrByMode(__ubuf__ T* dst, __ubuf__ T* src0, __ubuf__ T* src1, unsigned rptTimes)
141	    {
142	        if constexpr (DstStride > REPEAT_MAX || Src0RptStride > REPEAT_MAX || Src1RptStride > REPEAT_MAX) {
143	            for (int i = 0; i < rptTimes; i++) {
144	                BinInstr(dst + i * DstCols, src0 + i * Src0Cols, src1 + i * Src1Cols, 1, 0, 0, 0);
145	            }
146	        } else if constexpr (CntModeEn) {
147	            set_mask_count();
148	            set_vector_mask(0, rptTimes * ElemPerRpt);
149	            BinInstr(dst, src0, src1, 0, DstStride, Src0RptStride, Src1RptStride);
150	            set_mask_norm();
151	            set_vector_mask(-1, -1);
152	        } else {
153	            BinInstr(dst, src0, src1, rptTimes, DstStride, Src0RptStride, Src1RptStride);
154	        }
155	    }
156	
157	    template <int TmpCols, int SrcCols, uint32_t TmpStride, uint32_t SrcStride, uint8_t ElemPerRpt>
158	    PTO_INTERNAL static void FillTmp(__ubuf__ T* tmp, __ubuf__ T* src, int srcRptPerRow, int validRow, int validCol)
159	    {
160	        if (validCol >= 2 * ElemPerRpt) {
161	            // validcol大于等于2次repeat，将完整的2次repeat比较后写入tmp
162	            BinInstrByMode<true, TmpCols, SrcCols, SrcCols, TmpStride, SrcStride, SrcStride, ElemPerRpt>(
163	                tmp, src, src + ElemPerRpt, validRow);
164	            pipe_barrier(PIPE_V);
165	        }
166	    }
167	
168	    template <int TmpCols, int SrcCols, uint32_t TmpStride, uint32_t SrcStride, uint8_t ElemPerRpt>
169	    PTO_INTERNAL static void TmpProc(__ubuf__ T* tmp, __ubuf__ T* src, int srcRptPerRow, int validRow)
170	    {
171	        for (int i = 2; i < srcRptPerRow; ++i) {
172	            BinInstrByMode<true, TmpCols, TmpCols, SrcCols, TmpStride, TmpStride, SrcStride, ElemPerRpt>(
173	                tmp, tmp, src + i * ElemPerRpt, validRow);
174	            pipe_barrier(PIPE_V);
175	        }
176	    }
177	};
178	
179	template <typename TileDataOut, typename TileDataIn, bool idx = false>
180	PTO_INTERNAL void TRowReduceCheck(int validRow, int validCol, int dstValidRow)
181	{
182	    static_assert(
183	        TileDataOut::Loc == pto::TileType::Vec && TileDataIn::Loc == pto::TileType::Vec,
184	        "Fix: TROWREDUCE only support Vec Tile");
185	
186	    static_assert(
187	        TileDataIn::isRowMajor && TileDataIn::SFractal == SLayout::NoneBox,
188	        "Fix: TROWREDUCE only support Nd fractal Tile");
189	
190	    static_assert(
191	        (!TileDataOut::isBoxedLayout &&
192	         (TileDataOut::isRowMajor || (!TileDataOut::isRowMajor && TileDataOut::Cols == 1))),
193	        "Fix: TROWREDUCE only support Nd fractal Tile or DN Tile with Col is 1.");
194	
195	    using T = typename TileDataIn::DType;
196	    using TDst = typename TileDataOut::DType;
197	    static_assert(
198	        std::is_same_v<T, half> || std::is_same_v<T, float> || std::is_same_v<T, int32_t> || std::is_same_v<T, int16_t>,
199	        "Fix: TROWREDUCE input data type is not supported by this instruction. Supported types: half, float, int32, "
200	        "int16.");
201	
202	    static_assert(
203	        idx || std::is_same_v<typename TileDataOut::DType, typename TileDataIn::DType>,
204	        "Fix: TROWREDUCE input data type must be consistent with the output data type.");
205	
206	    PTO_ASSERT(validCol != 0 && validRow != 0, "Fix: TROWREDUCE input shape is invalid, validCol or validRow is 0.");
207	    PTO_ASSERT(validRow == dstValidRow, "Fix: TROWREDUCE input validRow must be consistent with the output validRow.");
208	}
209	
210	template <
211	    typename InstrOp, typename T, uint32_t DstCols, uint32_t SrcCols, uint8_t elemPerRpt, uint32_t dstRptStride,
212	    uint32_t srcRptStride>
213	PTO_INTERNAL void OneRepeatProc(
214	    __ubuf__ T* dst, __ubuf__ T* src, int validCol, int validRow, int remain, int rowRptTimes)
215	{
216	    if (validCol == elemPerRpt) {
217	        InstrOp::template ReduceInstrByMode<true, SrcCols, dstRptStride, srcRptStride, elemPerRpt>(dst, src, validRow);
218	        pipe_barrier(PIPE_V);
219	        return;
220	    }
221	
222	    unsigned rptTimes;
223	    SetContinuousMask(remain);
224	    do {
225	        rptTimes = rowRptTimes == 0 ? (validRow % REPEAT_MAX) : REPEAT_MAX;
226	        InstrOp::template ReduceInstrByMode<false, SrcCols, dstRptStride, srcRptStride, elemPerRpt>(dst, src, rptTimes);
227	        pipe_barrier(PIPE_V);
228	        rowRptTimes -= 1;
229	        dst += rptTimes * DstCols;
230	        src += rptTimes * SrcCols;
231	    } while (rowRptTimes >= 0);
232	
233	    set_vector_mask(-1, -1);
234	}
235	
236	template <typename InstrOp, typename T, typename TileOut, typename TileIn>
237	PTO_INTERNAL bool TryOptimizeFP32Reduce(__ubuf__ T* dst, __ubuf__ T* src, __ubuf__ T* tmp)
238	{
239	    if constexpr (!TileOut::isBoxedLayout && !TileOut::isRowMajor && TileOut::ValidCol == 1) {
240	        if constexpr (std::is_same_v<T, float>) {
241	            constexpr bool ShapeOf64x128 =
242	                TileIn::Rows == 64 && TileIn::ValidRow == 64 && TileIn::Cols == 128 && TileIn::ValidCol == 128;
243	            constexpr bool ShapeOf32x256 =
244	                TileIn::Rows == 32 && TileIn::ValidRow == 32 && TileIn::Cols == 256 && TileIn::ValidCol == 256;
245	            constexpr bool ShapeOf16x512 =
246	                TileIn::Rows == 16 && TileIn::ValidRow == 16 && TileIn::Cols == 512 && TileIn::ValidCol == 512;
247	            constexpr bool ShapeOf8x1024 =
248	                TileIn::Rows == 8 && TileIn::ValidRow == 8 && TileIn::Cols == 1024 && TileIn::ValidCol == 1024;
249	            if constexpr (ShapeOf64x128) {
250	                InstrOp::template ReduceOptFP32_64x128<TileIn::Rows, TileIn::ValidRow, TileIn::Cols, TileIn::ValidCol>(
251	                    dst, src, tmp);
252	                return true;
253	            } else if constexpr (ShapeOf32x256) {
254	                InstrOp::template ReduceOptFP32_32x256<TileIn::Rows, TileIn::ValidRow, TileIn::Cols, TileIn::ValidCol>(
255	                    dst, src, tmp);
256	                return true;
257	            } else if constexpr (ShapeOf16x512) {
258	                InstrOp::template ReduceOptFP32_16x512<TileIn::Rows, TileIn::ValidRow, TileIn::Cols, TileIn::ValidCol>(
259	                    dst, src, tmp);
260	                return true;
261	            } else if constexpr (ShapeOf8x1024) {
262	                InstrOp::template ReduceOptFP32_8x1024<TileIn::Rows, TileIn::ValidRow, TileIn::Cols, TileIn::ValidCol>(
263	                    dst, src, tmp);
264	                return true;
265	            }
266	        }
267	    }
268	    return false;
269	}
270	
271	template <typename InstrOp, typename T, typename TileDataOut, typename TileDataIn, typename TileDataTmp>
272	PTO_INTERNAL void TRowReduceInstr(__ubuf__ T* dst, __ubuf__ T* src, __ubuf__ T* tmp, int validCol, int validRow)
273	{
274	    if (TryOptimizeFP32Reduce<InstrOp, T, TileDataOut, TileDataIn>(dst, src, tmp)) {
275	        return;
276	    }
277	    constexpr uint8_t elemPerBlock = BLOCK_BYTE_SIZE / sizeof(T);
278	    constexpr uint8_t elemPerRpt = REPEAT_BYTE / sizeof(T);
279	    constexpr uint32_t dstRptStride = TileDataOut::Cols;
280	    constexpr uint32_t srcRptStride = TileDataIn::Cols / elemPerBlock;
281	    constexpr uint32_t tmpRptStride = TileDataTmp::Cols / elemPerBlock;
282	    int srcRptPerRow = validCol / elemPerRpt;
283	    int remain = validCol % elemPerRpt;
284	    int rowRptTimes = validRow / REPEAT_MAX; // 需要处理的行若超过uint8_max, 则拆分为多次进行循环
285	    unsigned rptTimes;
286	
287	    if (validCol <= elemPerRpt) {
288	        OneRepeatProc<InstrOp, T, TileDataOut::Cols, TileDataIn::Cols, elemPerRpt, dstRptStride, srcRptStride>(
289	            dst, src, validCol, validRow, remain, rowRptTimes);
290	        return;
291	    }
292	
293	    if (validCol < 2 * elemPerRpt) {
294	        // 解决 ccec 编译检查问题； 如果删除会导致copy_ubuf_to_ubuf编译错误，提醒第六、七个参数的范围必须是[0, 65535]
295	        if constexpr ((srcRptStride < BLOCK_MAX_PER_REPEAT) || (tmpRptStride < BLOCK_MAX_PER_REPEAT)) {
296	            return;
297	        }
298	        // 将满足一次repeat部分copy到dst
299	        pto_copy_ubuf_to_ubuf(
300	            tmp, src, validRow, BLOCK_MAX_PER_REPEAT, srcRptStride - BLOCK_MAX_PER_REPEAT,
301	            tmpRptStride - BLOCK_MAX_PER_REPEAT);
302	        pipe_barrier(PIPE_V);
303	    }
304	
305	    InstrOp::template FillTmp<TileDataTmp::Cols, TileDataIn::Cols, tmpRptStride, srcRptStride, elemPerRpt>(
306	        tmp, src, srcRptPerRow, validRow, validCol);
307	
308	    // 不足一次repeat的部分设置mask与tmp计算, 此时tmp必定存在有效数据
309	    if (remain > 0) {
310	        __ubuf__ T* srcP = src;
311	        __ubuf__ T* tmpP = tmp;
312	        SetContinuousMask(remain);
313	        do {
314	            rptTimes = rowRptTimes == 0 ? (validRow % REPEAT_MAX) : REPEAT_MAX;
315	            InstrOp::template BinInstrByMode<
316	                false, TileDataTmp::Cols, TileDataTmp::Cols, TileDataIn::Cols, tmpRptStride, tmpRptStride, srcRptStride,
317	                elemPerRpt>(tmpP, tmpP, srcP + srcRptPerRow * elemPerRpt, rptTimes);
318	            rowRptTimes -= 1;
319	            srcP += rptTimes * TileDataIn::Cols;
320	            tmpP += rptTimes * TileDataTmp::Cols;
321	        } while (rowRptTimes >= 0);
322	        set_vector_mask(-1, -1);
323	        pipe_barrier(PIPE_V);
324	    }
325	
326	    InstrOp::template TmpProc<TileDataTmp::Cols, TileDataIn::Cols, tmpRptStride, srcRptStride, elemPerRpt>(
327	        tmp, src, srcRptPerRow, validRow);
328	
329	    InstrOp::template ReduceInstrByMode<true, TileDataTmp::Cols, dstRptStride, tmpRptStride, elemPerRpt>(
330	        dst, tmp, validRow);
331	    pipe_barrier(PIPE_V);
332	}
333	
334	} // namespace pto
335	
336	#endif
