14	using namespace pto;
15	
16	template <typename T, int kGRows_, int kGCols_, int kTRows_, int kTCols_>
17	AICORE inline void runTROWSUM(__gm__ T __out__* out, __gm__ T __in__* src)
18	{
19	    using DynShapeDim5 = Shape<1, 1, 1, kGRows_, kGCols_>;
20	    using DynStridDim5 = Stride<kGCols_, kGCols_, kGCols_, kGCols_, 1>;
21	    using GlobalData = GlobalTensor<T, DynShapeDim5, DynStridDim5>;
22	    GlobalData srcGlobal(src);
23	    GlobalData dstGlobal(out);
24	
25	    using TileData = Tile<TileType::Vec, T, kTRows_, kTCols_, BLayout::RowMajor, -1, -1>;
26	    TileData srcTile(kTRows_, kTCols_);
27	    TileData tmpTile(kTRows_, kTCols_);
28	    TileData dstTile(kTRows_, kTCols_);
29	    TASSIGN(srcTile, 0x0);
30	    TASSIGN(tmpTile, 0x4000);
31	    TASSIGN(dstTile, 0x8000);
32	
33	    std::fill(dstTile.data(), dstTile.data() + kTRows_ * kTCols_, 0);
34	
35	    TLOAD(srcTile, srcGlobal);
36	    set_flag(PIPE_MTE2, PIPE_V, EVENT_ID0);
37	    wait_flag(PIPE_MTE2, PIPE_V, EVENT_ID0);
38	    TROWSUM(dstTile, srcTile, tmpTile);
39	    set_flag(PIPE_V, PIPE_MTE3, EVENT_ID0);
40	    wait_flag(PIPE_V, PIPE_MTE3, EVENT_ID0);
41	    TSTORE(dstGlobal, dstTile);
42	    out = dstGlobal.data();
43	}
44	
45	template <typename T, int kGRows_, int kGCols_, int kTRows_, int kTCols_>
46	void LaunchTROWSUM(T* out, T* src, void* stream)
47	{
48	    if constexpr (std::is_same_v<T, aclFloat16>) {
49	        runTROWSUM<half, kGRows_, kGCols_, kTRows_, kTCols_>((half*)(out), (half*)src);
50	    } else {
51	        runTROWSUM<T, kGRows_, kGCols_, kTRows_, kTCols_>(out, src);
52	    }
53	}
54	
55	template void LaunchTROWSUM<float, 64, 64, 64, 64>(float* out, float* src, void* stream);
